/* ============================================
   ClipCast — Global Styles
   ============================================ */

:root {
  --primary: #1868DB;
  --primary-dark: #1457b8;
  --accent: #FF613D;
  --accent-dark: #e55535;
  --dark: #292A2E;
  --gray-50: #F8F9FB;
  --gray-100: #F1F3F6;
  --gray-200: #E4E7EC;
  --gray-300: #D0D5DD;
  --gray-400: #98A2B3;
  --gray-500: #667085;
  --gray-600: #475467;
  --gray-700: #344054;
  --gray-800: #1D2939;
  --white: #ffffff;
  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --shadow-sm: 0 1px 2px rgba(16,24,40,0.05);
  --shadow-md: 0 4px 12px rgba(16,24,40,0.08);
  --shadow-lg: 0 12px 32px rgba(16,24,40,0.12);
  --max-width: 1200px;
  --font-sans: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
}

* { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; }
body {
  font-family: var(--font-sans);
  color: var(--dark);
  background: var(--white);
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; display: block; }
a { color: inherit; text-decoration: none; }
ul, ol { list-style: none; }

.container {
  width: 100%;
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

/* Typography */
.h1 { font-size: clamp(2.2rem, 5vw, 3.6rem); font-weight: 800; line-height: 1.1; letter-spacing: -0.02em; }
.h2 { font-size: clamp(1.6rem, 3.5vw, 2.4rem); font-weight: 700; line-height: 1.15; letter-spacing: -0.01em; }
.h3 { font-size: clamp(1.2rem, 2.5vw, 1.5rem); font-weight: 700; line-height: 1.25; }
.body { font-size: 1.05rem; color: var(--gray-600); max-width: 640px; }
.small { font-size: 0.875rem; color: var(--gray-500); }

/* Buttons */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 8px;
  padding: 12px 24px; border-radius: var(--radius-md); font-weight: 600; font-size: 0.95rem;
  border: none; cursor: pointer; transition: transform .15s, box-shadow .15s, background .15s;
}
.btn:hover { transform: translateY(-1px); }
.btn-primary { background: var(--primary); color: var(--white); }
.btn-primary:hover { background: var(--primary-dark); box-shadow: var(--shadow-md); }
.btn-accent { background: var(--accent); color: var(--white); }
.btn-accent:hover { background: var(--accent-dark); box-shadow: var(--shadow-md); }
.btn-outline { background: transparent; color: var(--dark); border: 1.5px solid var(--gray-300); }
.btn-outline:hover { border-color: var(--gray-400); background: var(--gray-50); }
.btn-ghost { background: transparent; color: var(--primary); }
.btn-ghost:hover { background: rgba(24,104,219,0.06); }
.btn-lg { padding: 14px 32px; font-size: 1.05rem; border-radius: var(--radius-lg); }

/* Nav */
.nav {
  position: sticky; top: 0; z-index: 100;
  background: rgba(255,255,255,0.85);
  backdrop-filter: saturate(140%) blur(12px);
  border-bottom: 1px solid var(--gray-200);
}
.nav-inner { display: flex; align-items: center; justify-content: space-between; height: 64px; }
.nav-logo { font-weight: 800; font-size: 1.25rem; color: var(--dark); display: flex; align-items: center; gap: 8px; }
.nav-logo .dot { width: 10px; height: 10px; border-radius: 50%; background: var(--accent); }
.nav-links { display: flex; align-items: center; gap: 28px; }
.nav-links a { font-size: 0.9rem; font-weight: 500; color: var(--gray-700); transition: color .15s; }
.nav-links a:hover { color: var(--primary); }
.nav-actions { display: flex; align-items: center; gap: 12px; }

/* Sections */
.section { padding: 80px 0; }
.section-alt { background: var(--gray-50); }
.section-header { text-align: center; margin-bottom: 56px; }
.section-header .h2 { margin-bottom: 12px; }
.section-header .body { margin: 0 auto; }

/* Cards */
.card {
  background: var(--white); border-radius: var(--radius-lg);
  border: 1px solid var(--gray-200); padding: 28px;
  transition: box-shadow .2s, transform .2s;
}
.card:hover { box-shadow: var(--shadow-lg); transform: translateY(-2px); }

/* Tags */
.tag {
  display: inline-flex; align-items: center; gap: 6px;
  padding: 4px 12px; border-radius: 999px; font-size: 0.8rem; font-weight: 600;
}
.tag-blue { background: rgba(24,104,219,0.08); color: var(--primary); }
.tag-orange { background: rgba(255,97,61,0.08); color: var(--accent); }
.tag-green { background: rgba(16,185,129,0.08); color: #059669; }

/* Footer */
.footer { background: var(--dark); color: var(--gray-300); padding: 64px 0 32px; }
.footer-grid { display: grid; grid-template-columns: repeat(6, 1fr); gap: 32px; }
.footer-col h4 { color: var(--white); font-size: 0.85rem; font-weight: 600; margin-bottom: 16px; text-transform: uppercase; letter-spacing: 0.05em; }
.footer-col a { display: block; font-size: 0.85rem; color: var(--gray-400); margin-bottom: 10px; transition: color .15s; }
.footer-col a:hover { color: var(--white); }
.footer-bottom { border-top: 1px solid rgba(255,255,255,0.08); margin-top: 48px; padding-top: 24px; display: flex; justify-content: space-between; align-items: center; font-size: 0.8rem; color: var(--gray-500); }

/* Cookie banner */
.cookie-banner {
  position: fixed; bottom: 0; left: 0; right: 0; z-index: 200;
  background: var(--white); border-top: 1px solid var(--gray-200);
  padding: 20px 0; box-shadow: var(--shadow-lg);
  transform: translateY(0); transition: transform .35s ease;
}
.cookie-banner.hidden { transform: translateY(120%); }
.cookie-inner { display: flex; align-items: center; justify-content: space-between; gap: 24px; flex-wrap: wrap; }
.cookie-text { font-size: 0.9rem; color: var(--gray-600); max-width: 720px; }
.cookie-actions { display: flex; gap: 10px; flex-wrap: wrap; }

/* Modal */
.modal-overlay {
  position: fixed; inset: 0; z-index: 300;
  background: rgba(0,0,0,0.45);
  display: flex; align-items: center; justify-content: center;
  opacity: 0; pointer-events: none; transition: opacity .25s ease;
}
.modal-overlay.open { opacity: 1; pointer-events: auto; }
.modal {
  background: var(--white); border-radius: var(--radius-xl);
  padding: 32px; width: 90%; max-width: 520px;
  box-shadow: var(--shadow-lg); transform: translateY(12px); transition: transform .25s ease;
}
.modal-overlay.open .modal { transform: translateY(0); }
.modal h3 { margin-bottom: 8px; }
.modal p { color: var(--gray-500); font-size: 0.9rem; margin-bottom: 20px; }
.modal-row { display: flex; align-items: center; justify-content: space-between; padding: 14px 0; border-bottom: 1px solid var(--gray-100); }
.modal-row:last-child { border-bottom: none; }
.modal-row strong { font-size: 0.95rem; }
.modal-row span { font-size: 0.85rem; color: var(--gray-500); }

/* Toggle switch */
.toggle { position: relative; width: 44px; height: 24px; }
.toggle input { opacity: 0; width: 0; height: 0; }
.toggle-slider {
  position: absolute; inset: 0; border-radius: 24px; background: var(--gray-300); cursor: pointer; transition: background .2s;
}
.toggle-slider::after {
  content: ''; position: absolute; top: 2px; left: 2px; width: 20px; height: 20px;
  border-radius: 50%; background: var(--white); transition: transform .2s; box-shadow: var(--shadow-sm);
}
.toggle input:checked + .toggle-slider { background: var(--primary); }
.toggle input:checked + .toggle-slider::after { transform: translateX(20px); }

/* Pricing */
.pricing-toggle {
  display: inline-flex; align-items: center; gap: 12px;
  background: var(--gray-100); padding: 6px; border-radius: var(--radius-lg);
}
.pricing-toggle button {
  padding: 8px 18px; border-radius: var(--radius-md); border: none; background: transparent;
  font-weight: 600; font-size: 0.9rem; cursor: pointer; color: var(--gray-600); transition: all .2s;
}
.pricing-toggle button.active { background: var(--white); color: var(--dark); box-shadow: var(--shadow-sm); }
.save-badge { display: inline-flex; align-items: center; padding: 3px 10px; border-radius: 999px; background: rgba(16,185,129,0.1); color: #059669; font-size: 0.75rem; font-weight: 700; }

/* Range slider */
.range-wrap { width: 100%; max-width: 320px; margin: 0 auto; }
.range-wrap input[type=range] { width: 100%; accent-color: var(--primary); }
.range-labels { display: flex; justify-content: space-between; font-size: 0.8rem; color: var(--gray-500); margin-top: 6px; }

/* FAQ */
.faq-item { border-bottom: 1px solid var(--gray-200); }
.faq-q {
  width: 100%; text-align: left; padding: 20px 0; font-size: 1.05rem; font-weight: 600;
  background: none; border: none; cursor: pointer; display: flex; align-items: center; justify-content: space-between; color: var(--dark);
}
.faq-q::after { content: '+'; font-size: 1.4rem; font-weight: 400; color: var(--gray-400); transition: transform .2s; }
.faq-item.open .faq-q::after { transform: rotate(45deg); }
.faq-a { max-height: 0; overflow: hidden; transition: max-height .35s ease, padding .35s ease; color: var(--gray-600); font-size: 0.95rem; }
.faq-item.open .faq-a { max-height: 400px; padding-bottom: 20px; }

/* Comparison table */
.compare-table { width: 100%; border-collapse: collapse; font-size: 0.9rem; }
.compare-table th, .compare-table td { padding: 14px 16px; text-align: left; border-bottom: 1px solid var(--gray-200); }
.compare-table th { font-weight: 600; color: var(--gray-700); background: var(--gray-50); position: sticky; top: 0; }
.compare-table td { color: var(--gray-600); }
.compare-table .check { color: var(--primary); font-weight: 700; }
.compare-table .dash { color: var(--gray-400); }

/* Testimonials */
.testimonial { background: var(--white); border-radius: var(--radius-lg); padding: 28px; border: 1px solid var(--gray-200); }
.testimonial p { font-size: 1rem; color: var(--gray-700); line-height: 1.6; margin-bottom: 16px; }
.testimonial .author { font-weight: 700; color: var(--dark); font-size: 0.9rem; }
.testimonial .role { font-size: 0.85rem; color: var(--gray-500); }

/* Login / Signup */
.auth-page { min-height: 100vh; display: flex; }
.auth-left { flex: 1; display: flex; flex-direction: column; justify-content: center; padding: 48px; max-width: 520px; margin: 0 auto; }
.auth-right { flex: 1; background: var(--gray-50); display: flex; align-items: center; justify-content: center; padding: 48px; }
.auth-logo { font-weight: 800; font-size: 1.25rem; display: flex; align-items: center; gap: 8px; margin-bottom: 40px; }
.auth-logo .dot { width: 10px; height: 10px; border-radius: 50%; background: var(--accent); }
.auth-h1 { font-size: 1.6rem; font-weight: 700; margin-bottom: 8px; }
.auth-sub { color: var(--gray-500); font-size: 0.95rem; margin-bottom: 28px; }
.social-btn {
  width: 100%; padding: 12px; border-radius: var(--radius-md); border: 1.5px solid var(--gray-200);
  background: var(--white); font-weight: 600; font-size: 0.9rem; cursor: pointer; display: flex; align-items: center; justify-content: center; gap: 10px;
  margin-bottom: 10px; transition: border-color .15s, background .15s;
}
.social-btn:hover { border-color: var(--gray-400); background: var(--gray-50); }
.divider { display: flex; align-items: center; gap: 12px; margin: 20px 0; color: var(--gray-400); font-size: 0.85rem; }
.divider::before, .divider::after { content: ''; flex: 1; height: 1px; background: var(--gray-200); }
.input {
  width: 100%; padding: 12px 14px; border-radius: var(--radius-md); border: 1.5px solid var(--gray-300);
  font-size: 0.95rem; outline: none; transition: border-color .15s, box-shadow .15s;
}
.input:focus { border-color: var(--primary); box-shadow: 0 0 0 3px rgba(24,104,219,0.1); }
.auth-footer { font-size: 0.8rem; color: var(--gray-500); margin-top: 20px; }
.auth-footer a { color: var(--primary); text-decoration: underline; }

/* Responsive */
@media (max-width: 1024px) {
  .footer-grid { grid-template-columns: repeat(3, 1fr); }
  .auth-page { flex-direction: column; }
  .auth-right { display: none; }
}
@media (max-width: 640px) {
  .footer-grid { grid-template-columns: repeat(2, 1fr); }
  .nav-links { display: none; }
  .section { padding: 56px 0; }
}

// ClipCast — Global Scripts

/* Cookie Banner */
(function () {
  const banner = document.getElementById('cookie-banner');
  if (!banner) return;
  const prefs = JSON.parse(localStorage.getItem('cookiePrefs') || 'null');
  if (prefs) banner.classList.add('hidden');

  document.getElementById('cookie-accept')?.addEventListener('click', () => {
    localStorage.setItem('cookiePrefs', JSON.stringify({ targeting: true, functional: true, performance: true }));
    banner.classList.add('hidden');
  });
  document.getElementById('cookie-reject')?.addEventListener('click', () => {
    localStorage.setItem('cookiePrefs', JSON.stringify({ targeting: false, functional: false, performance: false }));
    banner.classList.add('hidden');
  });
  document.getElementById('cookie-manage')?.addEventListener('click', () => {
    document.getElementById('cookie-modal')?.classList.add('open');
  });
  document.getElementById('cookie-modal-close')?.addEventListener('click', () => {
    document.getElementById('cookie-modal')?.classList.remove('open');
  });
  document.getElementById('cookie-modal-save')?.addEventListener('click', () => {
    const targeting = document.getElementById('toggle-targeting')?.checked ?? false;
    const functional = document.getElementById('toggle-functional')?.checked ?? false;
    const performance = document.getElementById('toggle-performance')?.checked ?? false;
    localStorage.setItem('cookiePrefs', JSON.stringify({ targeting, functional, performance }));
    document.getElementById('cookie-modal')?.classList.remove('open');
    banner.classList.add('hidden');
  });
})();

/* FAQ Accordion */
(function () {
  document.querySelectorAll('.faq-q').forEach(btn => {
    btn.addEventListener('click', () => {
      const item = btn.closest('.faq-item');
      const open = item.classList.contains('open');
      item.closest('.faq-list')?.querySelectorAll('.faq-item').forEach(i => i.classList.remove('open'));
      if (!open) item.classList.add('open');
    });
  });
})();

/* Pricing Toggle */
(function () {
  const monthlyBtn = document.getElementById('toggle-monthly');
  const annualBtn = document.getElementById('toggle-annual');
  if (!monthlyBtn || !annualBtn) return;

  const prices = {
    business: { monthly: 18, annual: 15 },
    business_ai: { monthly: 24, annual: 20 },
  };

  function setAnnual(isAnnual) {
    monthlyBtn.classList.toggle('active', !isAnnual);
    annualBtn.classList.toggle('active', isAnnual);
    document.getElementById('price-business')?.textContent = '$' + (isAnnual ? prices.business.annual : prices.business.monthly);
    document.getElementById('price-business-ai')?.textContent = '$' + (isAnnual ? prices.business_ai.annual : prices.business_ai.monthly);
    document.getElementById('period-business')?.textContent = isAnnual ? '/user/mo, billed annually' : '/user/mo';
    document.getElementById('period-business-ai')?.textContent = isAnnual ? '/user/mo, billed annually' : '/user/mo';
  }

  monthlyBtn.addEventListener('click', () => setAnnual(false));
  annualBtn.addEventListener('click', () => setAnnual(true));
})();

/* Team Size Slider */
(function () {
  const slider = document.getElementById('team-slider');
  const label = document.getElementById('team-label');
  if (!slider || !label) return;
  slider.addEventListener('input', () => {
    const v = parseInt(slider.value, 10);
    label.textContent = v + (v === 1 ? ' person' : ' people');
  });
})();

/* Comparison Table Expand */
(function () {
  document.querySelectorAll('[data-expand]').forEach(btn => {
    btn.addEventListener('click', () => {
      const target = document.getElementById(btn.dataset.expand);
      if (!target) return;
      const isHidden = target.hidden;
      target.hidden = !isHidden;
      btn.textContent = isHidden ? 'Show less' : 'See all features';
    });
  });
})();

/* Mobile nav */
(function () {
  const toggle = document.getElementById('mobile-nav-toggle');
  const menu = document.getElementById('mobile-nav');
  if (!toggle || !menu) return;
  toggle.addEventListener('click', () => {
    menu.hidden = !menu.hidden;
  });
})();
